import ast
import operator

# 定義された演算子対応表
OPERATORS = {
    '+': (ast.Add, operator.add),
    '-': (ast.Sub, operator.sub),
    '*': (ast.Mult, operator.mul),
    '/': (ast.Div, operator.truediv),
    '//': (ast.FloorDiv, operator.floordiv),
    '%': (ast.Mod, operator.mod),
    '**': (ast.Pow, operator.pow),
}

def eval_expression(expr):
    """
    数学式を評価する関数

    Args:
        expr: 計算したい文字列式（例: "3 + 4 * (2 - 1)"）

    Returns:
        計算結果

    Raises:
        ZeroDivisionError: 0 で割る場合
        SyntaxError: 不正な構文の場合
    """
    # ast を用いて安全にパースする
    parsed = ast.parse(expr, mode='eval')

    return _evaluate_expression(parsed.body)


def _visit(op):
    op_node = op
    if isinstance(op_node, ast.BinOp):
        left = _visit(op_node.left)
        right = _visit(op_node.right)

        # 割り算の場合のゼロ除算チェック
        if isinstance(op_node.op, ast.Div) and right == 0:
            raise ZeroDivisionError("division by zero")
        if isinstance(op_node.op, ast.FloorDiv) and right == 0:
            raise ZeroDivisionError("division by zero")
        if isinstance(op_node.op, ast.Mod) and right == 0:
            raise ZeroDivisionError("division by zero")

        return OPERATORS[type(op_node.op)][1](left, right)
    elif isinstance(op_node, ast.UnaryOp):
        operand = _visit(op_node.operand)
        if isinstance(op_node.op, ast.USub):
            return -operand
        elif isinstance(op_node.op, ast.UAdd):
            return operand
        elif isinstance(op_node.op, ast.Not):
            return not operand
    elif isinstance(op_node, ast.Num):  # Python 3.7 以前
        return op_node.n
    elif isinstance(op_node, ast.Constant):  # Python 3.8+
        return op_node.value

    raise ValueError(f"Unsupported operator type: {type(op_node)}")


def _evaluate_expression(node):
    if node is None:
        return 0
    return _visit(node)
